DO $inner$
DECLARE
  c   text;
  cen text;
BEGIN
  FOREACH c IN ARRAY ARRAY['oben','colacor','colacor_sc'] LOOP
    FOREACH cen IN ARRAY ARRAY['realista','otimista','pessimista'] LOOP
      PERFORM net.http_post(
        url := 'https://fzvklzpomgnyikkfkzai.supabase.co/functions/v1/fin-cashflow-engine',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-cron-secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='CRON_SECRET' LIMIT 1)
        ),
        body := jsonb_build_object('company', c, 'cenario', cen, 'save_snapshot', true),
        timeout_milliseconds := 120000
      );
    END LOOP;
  END LOOP;
END
$inner$;

