      headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='CRON_SECRET' LIMIT 1)),
      body:=jsonb_build_object('action','sync_contas_correntes','company',c), timeout_milliseconds:=60000);
  END LOOP;
END $inner$;

DO $inner$ DECLARE r record; BEGIN
  FOR r IN SELECT company, resource FROM public.fin_sync_cursor WHERE next_page IS NOT NULL LOOP
    PERFORM net.http_post(
      url := 'https://fzvklzpomgnyikkfkzai.supabase.co/functions/v1/omie-financeiro',
      headers := jsonb_build_object('Content-Type','application/json','x-cron-secret',(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='CRON_SECRET' LIMIT 1)),
      body := jsonb_build_object('action','sync_'||r.resource,'company',r.company),
      timeout_milliseconds := 150000);
  END LOOP;
END $inner$;

